    const soilTools = document.createElement('div');
    soilTools.className = 'pdSoilTools';
    soilTools.hidden = true;
    const soilToggle = document.createElement('button');
    soilToggle.type = 'button';
    soilToggle.id = 'pdToggleSoil';
    soilToggle.textContent = 'Вынимаемый грунт';
